from django.test import SimpleTestCase

from waldur_mastermind.matrix_chat import recovery_keys

# Generated by an independent implementation (matrix-nio's secret storage, checked
# against matrix-rust-sdk's vectors) for the key bytes(range(32)).
RECOVERY_KEY = "EsSz ykH7 LCZx 7Cae cmKD wcmY JRXi Ybtu 8iQ3 t8Ez nRwK pUY1"
KEY_INFO = {
    "algorithm": "m.secret_storage.v1.aes-hmac-sha2",
    "iv": "m6HQQhPK4K04HC7xFbIc3w",
    "mac": "GY/KerVsn+UK5QNKt3eScvJ1kkViXXG6TqazL/Zwjbs",
}
# The same check for a different key.
OTHER_KEY_INFO = {
    "algorithm": "m.secret_storage.v1.aes-hmac-sha2",
    "iv": "ipY3vly8tmIZNd5JnmU70w",
    "mac": "AyiqcamvFdehcNjzzGERKt32yZxP1qY4fG+rEOH/Yio",
}


class DecodeRecoveryKeyTest(SimpleTestCase):
    def test_decodes_the_key(self):
        self.assertEqual(
            recovery_keys.decode_recovery_key(RECOVERY_KEY), bytes(range(32))
        )

    def test_spacing_does_not_matter(self):
        self.assertEqual(
            recovery_keys.decode_recovery_key(RECOVERY_KEY.replace(" ", "")),
            bytes(range(32)),
        )

    def test_typo_fails_the_parity_check(self):
        typo = RECOVERY_KEY[:-1] + ("2" if RECOVERY_KEY[-1] != "2" else "3")
        with self.assertRaises(recovery_keys.InvalidRecoveryKey):
            recovery_keys.decode_recovery_key(typo)

    def test_rejects_non_base58_and_wrong_length(self):
        for value in ("not a key 0OIl", "EsSz ykH7", ""):
            with self.subTest(value=value):
                with self.assertRaises(recovery_keys.InvalidRecoveryKey):
                    recovery_keys.decode_recovery_key(value)


class RecoveryKeyOpensTest(SimpleTestCase):
    def test_opens_its_own_key(self):
        self.assertTrue(recovery_keys.recovery_key_opens(RECOVERY_KEY, KEY_INFO))

    def test_does_not_open_another_key(self):
        self.assertFalse(recovery_keys.recovery_key_opens(RECOVERY_KEY, OTHER_KEY_INFO))

    def test_unconfirmable_descriptions_are_false(self):
        for info in (
            None,
            {},
            {**KEY_INFO, "algorithm": "m.secret_storage.v2"},
            {"algorithm": KEY_INFO["algorithm"]},
        ):
            with self.subTest(info=info):
                self.assertFalse(recovery_keys.recovery_key_opens(RECOVERY_KEY, info))

    def test_garbage_key_is_false(self):
        self.assertFalse(recovery_keys.recovery_key_opens("garbage", KEY_INFO))
